const scanner=require("./scanner"),logger=require("../logger"),jobs=new Map,queue=[];let processing=!1;function makeId(){return`${Date.now().toString(36)}-${Math.random().toString(36).slice(2,10)}`}function createJob(options){const id=makeId(),job={id:id,status:"queued",options:options,createdAt:Date.now()};return jobs.set(id,job),queue.push(id),processQueue().catch(err=>logger.error("ScanJobs queue error:",err)),id}function getJob(id){return jobs.get(id)}async function processQueue(){if(!processing){for(processing=!0;queue.length>0;){const id=queue.shift(),job=jobs.get(id);if(job){job.status="running",job.startedAt=Date.now();try{const result=await scanner.scanWebsite(job.options);job.status="completed",job.result=result,job.completedAt=Date.now()}catch(err){logger.error(`Job ${id} failed:`,err.message||err),job.status="failed",job.error=err.message||String(err),job.completedAt=Date.now()}}}processing=!1}}module.exports={createJob:createJob,getJob:getJob};